import 'package:flutter/material.dart';

/// Zeigt einen Bestätigungsdialog "Fahrt beenden?" an.
///
/// Dieser Dialog wird asynchron aufgerufen und erwartet zwei Callbacks:
/// 1. [onConfirm]: Wird ausgeführt, wenn der Benutzer Ja wählt (Bestätigung).
/// 2. [onCancel]: Wird ausgeführt, wenn der Benutzer Nein wählt oder den Dialog schließt (Abbruch).
Future<void> showEndTripConfirmationDialog({
  required BuildContext context,
  required Future<void> Function() onConfirm,
  required Future<void> Function() onCancel,
}) async {
  await showDialog(
    context: context,
    builder: (BuildContext dialogContext) {
      return AlertDialog(
        title: const Text("Fahrt beenden?"),
        content: const Text("Möchten Sie die aktuelle Fahrt wirklich beenden und speichern?"),
        actions: <Widget>[
          TextButton(
            onPressed: () {
              // Beim Tippen auf "Nein" wird onCancel ausgeführt.
              if (Navigator.canPop(dialogContext)) {
                Future.microtask(() => onCancel());
                Navigator.pop(dialogContext); // Dialog schließen
              }
            },
            child: const Text("Nein"),
          ),
          TextButton(
            onPressed: () async {
              // Beim Tippen auf "Ja" wird onConfirm ausgeführt.
              if (Navigator.canPop(dialogContext)) {
                await onConfirm(); // Handler ausführen
                Navigator.pop(dialogContext); // Dialog schließen
              }
            },
            child: const Text("Ja"),
          ),
        ],
      );
    },
  );
}

